const icon = (name, extra='') => `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const features = [
  {title:'AI Medical Assistant',text:'Ask health questions and get clear, thoughtful explanations in everyday language.',icon:'chat',route:'assistant'},
  {title:'Smart Form Scanner',text:'Turn complicated medical paperwork into a simpler, reviewable checklist.',icon:'clipboard',route:'forms'},
  {title:'Prescription Analyzer',text:'Understand what is written on your prescription, without guessing unclear details.',icon:'pill',route:'prescriptions'},
  {title:'Medical Report Analyzer',text:'Make sense of report terminology, values, and the questions worth asking.',icon:'chart',route:'reports'}
];
const toolInfo = {
  forms:{title:'Medical Form Scanner',subtitle:'Extract visible fields and review every detail before you use it.',icon:'clipboard',intro:'Upload a medical form',tips:['Clearly marked fields can be organized for review.','Required fields are marked only when the form says so.','Fill blank fields yourself; we never invent medical details.'],label:'form'},
  prescriptions:{title:'Prescription Analyzer',subtitle:'Review medication details from your prescription with care.',icon:'pill',intro:'Upload a prescription',tips:['Check medicine names and dosages against the original.','Unclear handwriting is never treated as a fact.','Ask your pharmacist or doctor about ambiguous instructions.'],label:'prescription'},
  reports:{title:'Medical Report Analyzer',subtitle:'Understand written findings and lab values in plain language.',icon:'chart',intro:'Upload a medical report',tips:['Values and ranges are shown only when readable.','High or low flags come from the original report.','Medical images are not interpreted as radiology findings.'],label:'report'}
};
const dictionary = [
  {term:'Haemoglobin',short:'A protein in red blood cells that carries oxygen.',detail:'Haemoglobin helps transport oxygen from the lungs to the body. A haemoglobin test measures how much of it is in your blood.',why:'Doctors check it as part of a complete blood count when assessing general blood health.',context:'A result should be considered with the laboratory range and your medical history.'},
  {term:'Hypertension',short:'The medical term for high blood pressure.',detail:'Hypertension describes blood pressure that remains higher than recommended over time. One isolated reading does not necessarily establish it.',why:'Monitoring blood pressure helps clinicians assess long-term heart and blood vessel health.',context:'Measurements, circumstances, history, and individual risk all matter.'},
  {term:'Diabetes Mellitus',short:'A condition involving how the body regulates blood sugar.',detail:'Diabetes mellitus is a group of conditions in which blood glucose remains elevated because of how the body produces or uses insulin.',why:'Clinicians use blood glucose and other tests to understand blood sugar patterns.',context:'Diagnosis and treatment decisions require a qualified healthcare professional.'},
  {term:'Creatinine',short:'A waste product used to help assess kidney function.',detail:'Creatinine is produced by normal muscle activity and removed from the blood by the kidneys.',why:'A blood creatinine result may be used with other information to estimate kidney filtration.',context:'Muscle mass, hydration, medicines, and other factors may influence results.'},
  {term:'Cholesterol',short:'A waxy substance found in your blood and cells.',detail:'Your body needs cholesterol for cell membranes and hormones. Lipid tests often include LDL, HDL, and total cholesterol.',why:'Clinicians review a lipid profile as part of cardiovascular health assessment.',context:'Individual results are interpreted alongside age, history, and other risk factors.'},
  {term:'Anaemia',short:'A condition where the blood carries less oxygen than expected.',detail:'Anaemia can involve a lower-than-expected number of red blood cells or haemoglobin. There are many possible causes.',why:'A clinician may use a complete blood count and additional tests to investigate.',context:'Do not infer a cause from one number alone.'},
  {term:'Platelets',short:'Blood cells that help your blood clot.',detail:'Platelets are small cell fragments involved in stopping bleeding and helping wounds heal.',why:'A platelet count is usually part of a complete blood count.',context:'A count is considered together with symptoms and other test results.'},
  {term:'Bilirubin',short:'A substance produced when old red blood cells break down.',detail:'Bilirubin is processed by the liver and leaves the body through bile.',why:'Doctors may check it in liver panels or when investigating jaundice.',context:'Different forms of bilirubin and the clinical situation affect interpretation.'},
  {term:'ECG',short:'A recording of the heart’s electrical activity.',detail:'An electrocardiogram (ECG or EKG) uses sensors on the skin to record electrical signals from the heart.',why:'It can help clinicians assess heart rhythm and other electrical patterns.',context:'A trained professional should interpret the trace alongside symptoms.'},
  {term:'MRI',short:'A scan that uses magnets and radio waves to create images.',detail:'Magnetic resonance imaging creates detailed pictures of structures inside the body without using X-rays.',why:'Clinicians order an MRI to examine specific tissues or areas in more detail.',context:'Only a qualified professional can interpret imaging findings in context.'}
];
const state = {route:'home',menu:false,ai:false,providers:[],provider:localStorage.getItem('medi-guide-provider')||'',supabaseConfigured:false,supabase:null,account:null,authBusy:false,docs:[],activeDoc:null,chat:[{role:'assistant',content:'Hello! I’m Medi Guide, an educational health information assistant. Ask me a general question or attach a document to discuss its extracted text. I can’t diagnose or replace your clinician.'}],chatContext:null,chatBusy:false,followup:'',followupBusy:false,processing:false,user:'',term:null,search:''};
const $ = selector => document.querySelector(selector);
const route = () => (location.hash.replace(/^#\/?/,'').split('?')[0] || 'home').replace(/\/$/,'');
const go = path => {location.hash='#/'+path; if(route()===path) render();};
const toast = text => {const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3900)};
const notice = (text,type='') => `<div class="notice ${type}">${icon(type==='warning'||type==='error'?'alert':'info')}<span>${text}</span></div>`;
const providerNames={gemini:'Google Gemini',groq:'Groq',openrouter:'OpenRouter Free',cohere:'Cohere (evaluation)'};
function providerPicker(){return state.providers.length?`<div class="provider-control"><label for="ai-provider">AI provider</label><select id="ai-provider" aria-label="Choose AI provider">${state.providers.map(p=>`<option value="${p}" ${state.provider===p?'selected':''}>${providerNames[p]}</option>`).join('')}</select>${state.provider==='cohere'?'<small>Cohere trial keys are for evaluation, not a free production plan.</small>':''}</div>`:`<span class="status-badge off">AI not configured</span>`}
function accountName(user){return user?.user_metadata?.full_name?.trim()||user?.email||''}
function setAccount(user){const old=state.account?.id;state.account=user||null;state.user=accountName(user);if(old&&old!==user?.id){state.docs=[];state.activeDoc=null;state.chatContext=null}render();if(user&&old!==user.id)loadSavedDocs()}
async function loadSavedDocs(){if(!state.supabase||!state.account)return;const userId=state.account.id;const {data,error}=await state.supabase.from('documents').select('id,kind,name,extracted_text,result,ai_analyzed,created_at').order('created_at',{ascending:false}).limit(30);if(state.account?.id!==userId)return;if(error){toast('Could not load saved history. Run the Supabase schema SQL first.');return}const saved=(data||[]).filter(d=>toolInfo[d.kind]).map(d=>({id:d.id,kind:d.kind,name:d.name,text:d.extracted_text,result:d.result||{},aiAnalyzed:d.ai_analyzed,saved:true,date:new Date(d.created_at).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}),error:''}));state.docs=[...state.docs.filter(d=>!d.saved),...saved];render()}
async function saveDocument(doc){if(!state.supabase||!state.account){toast('Sign in to save documents securely to your Supabase account.');go('login');return}const record={user_id:state.account.id,kind:doc.kind,name:doc.name,extracted_text:doc.text,result:doc.result,ai_analyzed:doc.aiAnalyzed};const query=doc.saved?state.supabase.from('documents').update(record).eq('id',doc.id):state.supabase.from('documents').insert(record);const {data,error}=await query.select('id').single();if(error){toast('Could not save: '+error.message);return}doc.id=data.id;doc.saved=true;toast('Saved to your Supabase account.');render()}
async function deleteDocument(doc){if(doc.saved&&state.supabase){const {error}=await state.supabase.from('documents').delete().eq('id',doc.id);if(error){toast('Could not delete: '+error.message);return}}state.docs=state.docs.filter(d=>d!==doc);if(state.activeDoc===doc)state.activeDoc=null;if(state.chatContext===doc)state.chatContext=null;render()}
const brand = () => `<a class="brand" href="#/home" aria-label="Medi Guide home"><span class="brand-mark">${icon('cross')}</span>Medi Guide</a>`;
const themeLabel = () => document.documentElement.dataset.theme==='dark'?'Switch to light theme':'Switch to dark theme';
const themeButton = () => `<button class="theme-toggle" id="theme-toggle" type="button" aria-label="${themeLabel()}" title="${themeLabel()}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button>`;
function toggleTheme(){
  const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';
  document.documentElement.dataset.theme=theme;
  document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#0d171e':'#f8fcfb';
  try{localStorage.setItem('medi-guide-theme',theme)}catch{}
  const button=$('#theme-toggle');
  if(button){button.innerHTML=icon(theme==='dark'?'sun':'moon');button.setAttribute('aria-label',themeLabel());button.title=themeLabel()}
}
const header = () => `<header class="topbar"><div class="container topbar-inner">${brand()}<nav class="desktop-nav" aria-label="Main navigation"><a href="#/home">Home</a><div class="nav-dropdown"><button class="nav-dropdown-btn" type="button">Features ${icon('chevron','icon-sm')}</button><div class="dropdown-panel">${features.map(f=>`<a href="#/${f.route}">${icon(f.icon,'icon-sm')}${f.title}</a>`).join('')}<a href="#/dictionary">${icon('book','icon-sm')}Medical Dictionary</a></div></div><a href="#/about">About Us</a><a href="#/privacy">Privacy & Security</a></nav><div class="header-actions">${themeButton()}<a class="login-link btn btn-plain" href="#/${state.user?'dashboard':'login'}">${state.user?'Dashboard':'Log in'}</a><a class="btn btn-primary btn-sm" href="#/${state.user?'dashboard':'signup'}">${state.user?'Open workspace':'Get Started'} ${icon('arrow','icon-sm')}</a><button class="menu-btn" id="menu-toggle" aria-label="Toggle menu" aria-expanded="${state.menu}">${icon(state.menu?'close':'menu')}</button></div></div><nav class="mobile-nav ${state.menu?'open':''}" aria-label="Mobile navigation"><a href="#/home">Home</a>${features.map(f=>`<a href="#/${f.route}">${f.title}</a>`).join('')}<a href="#/dictionary">Medical Dictionary</a><a href="#/dashboard">Dashboard</a><a href="#/history">Document History</a><a href="#/about">About Us</a><a href="#/privacy">Privacy & Security</a><a href="#/${state.user?'profile':'login'}">${state.user?'Profile':'Log in / Sign up'}</a></nav></header>`;
const footer = () => `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p>Your health documents, made simple. Clarity and confidence for every step of your health journey.</p></div><div><h4>Explore</h4><a href="#/assistant">AI Assistant</a><a href="#/forms">Form Scanner</a><a href="#/prescriptions">Prescriptions</a><a href="#/reports">Report Analyzer</a></div><div><h4>Company</h4><a href="#/about">About Us</a><a href="#/dictionary">Medical Dictionary</a><a href="#/privacy">Privacy Policy</a><a href="#/terms">Terms & Conditions</a></div><div><h4>Get in touch</h4><a href="mailto:hello@mediguide.example">hello@mediguide.example</a><p>Have a question? We’re here to help you find your way.</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Medi Guide. All rights reserved.</span><span>Medical disclaimer: Information here is educational, not a diagnosis or medical advice. For emergencies, call your local emergency number.</span></div></div></footer>`;
function home(){return `<main><section class="hero"><div class="container hero-inner"><div class="hero-copy"><span class="pill">${icon('sparkle')} A clearer way to understand your health</span><h1>Understand Your Health. <span>Simplify Your Medical Journey.</span></h1><p>Scan medical documents, understand prescriptions, analyze reports, and get instant AI-powered medical guidance with Medi Guide.</p><div class="hero-ctas"><a class="btn btn-primary" href="#/signup">Get Started ${icon('arrow','icon-sm')}</a><a class="btn btn-outline" href="#/home" data-scroll="features">Explore Features ${icon('arrow','icon-sm')}</a></div><div class="hero-trust"><div class="avatar-stack" aria-hidden="true"><span>👩🏻</span><span>👨🏽</span><span>👩🏾</span></div><span>Made for clearer, more confident conversations about care</span></div></div><div class="hero-visual" aria-label="Healthcare professional and document illustration"><div class="visual-orbit"></div><div class="photo-frame"><img src="https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=900&q=85&fit=crop" alt="Friendly healthcare professional" loading="eager"></div><div class="float-card float-top"><span class="float-icon">${icon('shield')}</span><span><strong>Understand with care</strong><small>Review every detail</small></span></div><div class="float-card float-bottom"><strong>${icon('file','icon-sm')} Your document, simplified</strong><small>Clear insights, in everyday language</small><div class="progress-track"><i></i></div></div><span class="sparkle">${icon('sparkle')}</span></div></div></section><div class="trust-strip"><div class="container trust-inner"><p>Built around what matters</p><span class="trust-point">${icon('shield')} Privacy-minded by design</span><span class="trust-point">${icon('check')} No guessing missing details</span><span class="trust-point">${icon('heart')} Human care comes first</span></div></div><section id="features" class="section features"><div class="container"><div class="section-heading"><span class="eyebrow">Everything in one place</span><h2>Healthcare paperwork, made a little less overwhelming.</h2><p>Helpful tools to turn complex information into something you can actually understand.</p></div><div class="feature-grid">${features.map(f=>`<a href="#/${f.route}" class="feature-card"><span class="feature-icon">${icon(f.icon,'icon-lg')}</span><h3>${f.title}</h3><p>${f.text}</p><span class="text-link">Explore feature ${icon('arrow','icon-sm')}</span></a>`).join('')}</div></div></section><section class="section how"><div class="container"><div class="section-heading"><span class="eyebrow">How it works</span><h2>Simple steps. Better understanding.</h2><p>From upload to insight, you’re always in control of your information.</p></div><div class="steps-grid"><div class="step"><span class="step-circle">${icon('upload','icon-lg')}</span><span class="step-num">01</span><h3>Upload your document</h3><p>Choose a medical form, prescription, or report from your device, or use your camera.</p></div><div class="step"><span class="step-circle">${icon('sparkle','icon-lg')}</span><span class="step-num">02</span><h3>Review the details</h3><p>We organize readable text for you. Check and correct anything that doesn’t look right.</p></div><div class="step"><span class="step-circle">${icon('chat','icon-lg')}</span><span class="step-num">03</span><h3>Ask better questions</h3><p>Get plain-language explanations and prepare for a more informed conversation with your doctor.</p></div></div></div></section><section class="section why"><div class="container why-grid"><div class="why-art"><div class="art-document"><span class="art-head">${icon('heart','icon-lg')}</span><span class="bar medium"></span><span class="bar"></span><span class="bar short"></span><span class="bar"></span><span class="bar medium"></span></div><div class="art-check">${icon('check')} Ready to review</div></div><div class="why-content"><span class="eyebrow">Why Medi Guide</span><h2>A little more clarity. A lot more confidence.</h2><p>Medical language shouldn't stand between you and understanding your own health information.</p><div class="benefit"><span class="check">${icon('check','icon-sm')}</span><div><strong>Plain language, always</strong><p>Complex terms explained in ways that make sense.</p></div></div><div class="benefit"><span class="check">${icon('check','icon-sm')}</span><div><strong>You stay in control</strong><p>Review and edit extracted information before relying on it.</p></div></div><div class="benefit"><span class="check">${icon('check','icon-sm')}</span><div><strong>Careful by design</strong><p>Uncertain information stays uncertain. Professional care remains essential.</p></div></div><a class="btn btn-primary" href="#/about">More about us ${icon('arrow','icon-sm')}</a></div></div></section><section class="privacy-band"><div class="container privacy-inner"><div><span class="eyebrow">Your privacy matters</span><h2>Your information. Your choice.</h2><p>Files are processed in your browser. We don’t store your uploaded documents on our server. AI requests send extracted text to the configured provider only when you choose to analyze or ask a question.</p></div><a class="btn" href="#/privacy">How we handle data ${icon('arrow','icon-sm')}</a></div></section><section class="section faq"><div class="container"><div class="section-heading"><span class="eyebrow">Good to know</span><h2>Frequently asked questions</h2><p>Honest answers to help you use Medi Guide with confidence.</p></div><div class="faq-list">${[
['Is Medi Guide a doctor?','No. Medi Guide provides general educational information and helps organize document text. It cannot diagnose, prescribe, or replace a qualified healthcare professional.'],
['Can I trust every scanned detail?','OCR and AI can make mistakes, especially with handwriting or poor-quality scans. Always compare the results with the original and confirm unclear information with your clinician or pharmacist.'],
['What happens to my documents?','OCR runs in your browser. Original files are not stored on our server. You can choose to save extracted text privately in Supabase, or send it to your selected AI provider when you request analysis.'],
['What files can I upload?','PDF, JPG, JPEG, and PNG files up to 15 MB. PDF text extraction supports the first five pages, with OCR fallback where possible.'],
['Can I use it for an emergency?','No. If you think you or someone else may be experiencing a medical emergency, contact local emergency services immediately.']
].map(([q,a])=>`<details class="faq-item"><summary>${q}${icon('plus','icon-sm')}</summary><p>${a}</p></details>`).join('')}</div></div></section></main>${footer()}`}
const sideLinks=[['dashboard','activity','Overview'],['assistant','chat','AI Doctor Assistant'],['forms','clipboard','Form Scanner'],['prescriptions','pill','Prescriptions'],['reports','chart','Report Analyzer'],['dictionary','book','Medical Dictionary'],['history','clock','Document History'],['profile','user','Profile']];
function shell(content){return `<div class="app-shell"><aside class="sidebar"><div class="sidebar-label">Workspace</div>${sideLinks.slice(0,6).map(([r,i,t])=>`<a class="side-link ${state.route===r?'active':''}" href="#/${r}">${icon(i)}${t}</a>`).join('')}<div class="sidebar-label">Account</div>${sideLinks.slice(6).map(([r,i,t])=>`<a class="side-link ${state.route===r?'active':''}" href="#/${r}">${icon(i)}${t}</a>`).join('')}<div class="sidebar-note">${icon('shield')}<strong>You're in control</strong><p>Files stay in your browser until you choose to save extracted text to Supabase or send it to AI.</p></div></aside><main class="workspace">${content}</main></div>`}
const pageTop = (title,subtitle,action='') => `<div class="page-top"><div><span class="eyebrow">Medi Guide workspace</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
function dashboard(){return shell(`${pageTop(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}${state.user?', '+esc(state.user.split('@')[0]):''} 👋`,'Your health information, one step at a time.',providerPicker())}<div class="welcome-card"><div><h2>A clearer path starts here.</h2><p>Upload a document or ask a question. You decide what to share, and you can review everything we extract.</p><a href="#/reports" class="btn">Analyze a document ${icon('arrow','icon-sm')}</a></div><span class="welcome-symbol">${icon('heart')}</span></div><div class="mini-heading"><h2>What would you like to do?</h2></div><div class="quick-grid">${features.map(f=>`<a href="#/${f.route}" class="quick-card"><span class="feature-icon">${icon(f.icon)}</span><strong>${f.title}</strong><p>${f.text}</p>${icon('arrow','icon-sm')}</a>`).join('')}</div><div class="dashboard-bottom"><div class="panel"><div class="mini-heading" style="margin:0 0 10px"><h2>Recent documents</h2><a href="#/history" class="text-link">View all ${icon('arrow','icon-sm')}</a></div>${state.docs.length?state.docs.slice(0,3).map(historyRow).join(''):`<div class="empty-state">${icon('file')}<strong>No documents yet</strong><p>Your session and saved documents will appear here.</p></div>`}</div><div class="panel"><h3>A few things to remember</h3><div class="tip-row">${icon('check')}<span>Always verify extracted details with the original document.</span></div><div class="tip-row">${icon('heart')}<span>Use these tools to support, not replace, conversations with your care team.</span></div><div class="tip-row">${icon('shield')}<span>Only documents you explicitly save are stored in your Supabase account.</span></div></div></div>`)}
function toolPage(kind){const info=toolInfo[kind],doc=state.activeDoc && state.activeDoc.kind===kind?state.activeDoc:null;return shell(`${pageTop(info.title,info.subtitle,providerPicker())}<div class="tool-layout"><div class="panel"><div class="upload-zone" id="upload-zone" role="button" tabindex="0" aria-label="Upload a ${info.label}"><span class="upload-icon">${icon('upload','icon-lg')}</span><h3>${info.intro}</h3><p>Drag and drop a file here, or choose one below.</p><div class="upload-actions"><button type="button" class="btn btn-primary btn-sm" id="browse-btn">${icon('file','icon-sm')} Browse files</button><button type="button" class="btn btn-outline btn-sm" id="camera-btn">${icon('camera','icon-sm')} Use camera</button></div><small>PDF, JPG or PNG · Up to 15 MB · First 5 PDF pages</small></div><input class="hidden" type="file" id="document-input" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" aria-label="Choose document"><input class="hidden" type="file" id="camera-input" accept="image/*" capture="environment" aria-label="Take document photo">${doc?`<div class="file-details"><div><span class="file-icon">${icon('file')}</span><span><strong>${esc(doc.name)}</strong><small>${esc(doc.date)} · ${doc.text?'Text extracted':'Awaiting extraction'}</small></span></div><button type="button" id="clear-doc" aria-label="Remove document">${icon('close','icon-sm')}</button></div>`:''}${state.processing?`<div class="processing"><div class="spinner"></div><strong>Reading your document...</strong><p>OCR may take a moment, especially for scanned PDFs.</p></div>`:''}${doc&&!state.processing?results(doc):''}</div><aside class="tool-side"><div class="panel"><span class="feature-icon">${icon(info.icon)}</span><h3>Before you begin</h3><ul class="guide-list">${info.tips.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><div class="divider"></div><div class="small-label">Your privacy</div><p style="font-size:12px;margin:0">OCR happens in your browser. If AI is enabled, extracted text is sent to the configured provider only when you request analysis.</p></div>${notice('<strong>Important:</strong> Medi Guide is for education only, not diagnosis or treatment. In an emergency, contact local emergency services.','warning')}</aside></div>`)}
function results(doc){const r=doc.result||{},isAI=doc.aiAnalyzed;return `<div class="results"><div class="results-head"><h2>Review your results</h2><span class="status-badge ${isAI?'':'off'}">${isAI?'AI-assisted':'OCR / manual review'}</span></div>${doc.error?notice(esc(doc.error),'warning'):''}${r.summary?`<div class="summary-box"><strong>At a glance</strong><p>${esc(r.summary)}</p></div>`:''}${doc.kind==='forms'?formResults(doc):doc.kind==='prescriptions'?prescriptionResults(doc):reportResults(doc)}${(r.warnings||[]).length?`<div class="list-box"><strong>Check these details</strong><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}${(r.questions||[]).length?`<div class="list-box"><strong>Questions for your care team</strong><ul>${r.questions.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}<div class="result-actions">${doc.kind==='forms'?`<button class="btn btn-primary btn-sm" id="download-pdf">${icon('download','icon-sm')} Download reviewed fields PDF</button>`:''}${state.ai&&!doc.aiAnalyzed&&doc.text?`<button class="btn btn-outline btn-sm" id="retry-ai">${icon('sparkle','icon-sm')} Analyze with AI (sends text)</button>`:''}<button class="btn btn-soft btn-sm" id="save-doc">${icon('shield','icon-sm')} ${doc.saved?'Update saved copy':'Save to my account'}</button><a class="btn btn-outline btn-sm" href="#/assistant" id="ask-about-doc">${icon('chat','icon-sm')} Ask about this document</a></div>${doc.kind==='forms'?`<p style="font-size:11px;margin-top:10px">The download is a summary of your reviewed fields, not an edited copy of the original form.</p>`:''}<div class="followup"><h3>Ask a follow-up about this document</h3><form id="followup-form"><input class="input" id="followup-question" placeholder="e.g. What does this term mean?" aria-label="Follow-up question" required><button class="btn btn-primary btn-sm" ${state.followupBusy?'disabled':''}>${state.followupBusy?'Thinking...':'Ask'}</button></form>${state.followup?`<div class="followup-answer">${esc(state.followup)}</div>`:''}</div><details class="raw-text"><summary>View extracted text to verify against your original</summary><pre>${esc(doc.text||'No readable text was found.')}</pre></details></div>`}
const editInput=(key,index,field,value,placeholder='Not specified')=>`<input data-edit="${key}" data-index="${index}" data-field="${field}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${esc(field)} for row ${index+1}">`;
function formResults(doc){let fields=doc.result.fields||[];return `<div class="small-label">Extracted fields · edit before use</div>${fields.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Field</th><th>Your verified answer</th><th>Required?</th><th></th></tr></thead><tbody>${fields.map((f,i)=>`<tr><td>${editInput('fields',i,'label',f.label,'Field label')}${f.unclear?'<span class="tag alert">Check label</span>':''}</td><td>${editInput('fields',i,'value',f.value,'Enter only verified information')}</td><td><input type="checkbox" data-edit="fields" data-index="${i}" data-field="required" ${f.required?'checked':''} aria-label="Required field ${i+1}"></td><td><button class="icon-button" data-remove="fields" data-index="${i}" aria-label="Remove field">${icon('trash','icon-sm')}</button></td></tr>`).join('')}</tbody></table></div>`:notice('No fields were reliably identified. Add the fields you can verify from the original form.','warning')}<div class="result-actions"><button class="btn btn-soft btn-sm" data-add="fields">${icon('plus','icon-sm')} Add a field</button></div>${fields.some(f=>f.required&&!String(f.value||'').trim())?notice('One or more fields marked required are still blank.','warning'):''}`}
function prescriptionResults(doc){
  const r=doc.result, meds=r.medicines||[];
  return `<div class="small-label">Prescription details · verify against the original</div>
    ${meds.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Medicine</th><th>Dosage</th><th>Frequency</th><th>Duration</th><th></th></tr></thead><tbody>${meds.map((m,i)=>`<tr><td>${editInput('medicines',i,'name',m.name)}${m.unclear?'<span class="tag alert">Unclear — verify</span>':''}</td><td>${editInput('medicines',i,'dosage',m.dosage)}</td><td>${editInput('medicines',i,'frequency',m.frequency)}</td><td>${editInput('medicines',i,'duration',m.duration)}</td><td><button class="icon-button" data-remove="medicines" data-index="${i}" aria-label="Remove medicine">${icon('trash','icon-sm')}</button></td></tr>`).join('')}</tbody></table></div>
    ${meds.map((m,i)=>`<div class="field" style="margin-top:14px"><label>Instructions for ${esc(m.name||'medicine '+(i+1))}</label><input data-edit="medicines" data-index="${i}" data-field="instructions" value="${esc(m.instructions||'')}" placeholder="Only enter instructions you can verify"></div>${m.purpose?`<p style="font-size:12px;margin-top:-9px">General purpose: ${esc(m.purpose)}</p>`:''}`).join('')}`:notice('No medication details have been confirmed. Read the source prescription and add only what you can verify. Never rely on uncertain handwriting.','warning')}
    <div class="result-actions"><button class="btn btn-soft btn-sm" data-add="medicines">${icon('plus','icon-sm')} Add verified medicine</button></div>
    <div class="field" style="margin-top:20px"><label>Prescription date, if readable</label><input data-result-field="date" value="${esc(r.date||'')}" placeholder="Not specified"></div>
    <div class="field"><label>Doctor's notes, if readable</label><textarea data-result-field="doctorNotes" placeholder="Not specified">${esc(r.doctorNotes||'')}</textarea></div>
    ${(r.abbreviations||[]).length?`<div class="list-box"><strong>Abbreviations</strong><ul>${r.abbreviations.map(a=>`<li>${esc(a.term)} — ${esc(a.meaning)}</li>`).join('')}</ul></div>`:''}`
}
function reportResults(doc){const rows=doc.result.parameters||[];return `<div class="small-label">Reported values · copied from readable text</div>${rows.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Parameter</th><th>Value</th><th>Unit</th><th>Report's range</th><th>Source flag</th><th></th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td>${editInput('parameters',i,'name',p.name)}</td><td>${editInput('parameters',i,'value',p.value)}</td><td>${editInput('parameters',i,'unit',p.unit)}</td><td>${editInput('parameters',i,'range',p.range)}</td><td>${p.flag?`<span class="tag alert">${esc(p.flag)}</span>`:'—'}</td><td><button class="icon-button" data-remove="parameters" data-index="${i}" aria-label="Remove parameter">${icon('trash','icon-sm')}</button></td></tr>`).join('')}</tbody></table></div>${rows.some(p=>p.explanation)?`<div class="list-box"><strong>What these terms generally mean</strong><ul>${rows.filter(p=>p.explanation).map(p=>`<li><b>${esc(p.name)}:</b> ${esc(p.explanation)}</li>`).join('')}</ul></div>`:''}`:notice('No clearly labeled values were identified. This may be an imaging report or an unclear scan. Check the source text below; AI analysis may help with written findings if enabled.','warning')}<p style="font-size:11px;margin:12px 0 0">A source flag appears only when explicitly marked in the document. A missing flag does not mean a result is normal.</p><div class="result-actions"><button class="btn btn-soft btn-sm" data-add="parameters">${icon('plus','icon-sm')} Add a verified value</button></div>`}
function assistant(){return shell(`${pageTop('AI Doctor Assistant','A calmer place to ask health questions and understand medical language.',providerPicker())}<div class="chat-shell"><div class="panel chat-main"><div class="chat-head"><span class="chat-avatar">${icon('sparkle')}</span><div><strong>Medi Guide Assistant</strong><small>${state.chatContext?'Discussing: '+esc(state.chatContext.name):'Educational guidance, not medical advice'}</small></div></div><div class="chat-messages" id="chat-messages">${state.chat.map(m=>`<div class="chat-message ${m.role}">${esc(m.content)}</div>`).join('')}${state.chatBusy?`<div class="chat-message assistant">Thinking...</div>`:''}</div><div class="chat-suggestions">${['What is haemoglobin?','Explain my report in simple words','What should I ask my doctor?'].map(q=>`<button type="button" data-suggest="${esc(q)}">${q}</button>`).join('')}</div><form class="chat-compose" id="chat-form"><button type="button" class="icon-button" id="chat-upload-inline" aria-label="Attach document">${icon('upload','icon-sm')}</button><input id="chat-input" placeholder="Ask a health question..." aria-label="Your message" autocomplete="off" maxlength="3000" required><button class="btn btn-primary btn-sm" aria-label="Send message" ${state.chatBusy?'disabled':''}>${icon('send','icon-sm')}</button></form></div><aside class="panel chat-aside"><span class="feature-icon">${icon('file')}</span><h3>Ask about a document</h3><p>Choose a saved or session document, or upload a new file. We’ll use its extracted text as context.</p><div class="field"><label for="context-doc">Session document</label><select id="context-doc"><option value="">No document selected</option>${state.docs.map(d=>`<option value="${d.id}" ${state.chatContext?.id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><button type="button" class="btn btn-outline btn-sm" id="chat-upload">${icon('upload','icon-sm')} Upload document</button><input class="hidden" id="chat-file" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"><div class="divider"></div><h3>Trusted places to learn</h3><p><a class="text-link" href="https://medlineplus.gov/" target="_blank" rel="noopener noreferrer">MedlinePlus ↗</a><br><a class="text-link" href="https://www.nhs.uk/conditions/" target="_blank" rel="noopener noreferrer">NHS health A–Z ↗</a><br><a class="text-link" href="https://www.who.int/health-topics" target="_blank" rel="noopener noreferrer">WHO health topics ↗</a></p><div class="divider"></div>${notice(state.ai?'AI responses can be wrong. Free tiers have quotas and may retain prompts. Verify with a clinician.':'AI chat requires a configured provider and a Supabase sign-in. The medical dictionary works without AI.','warning')}</aside></div>`)}
function dictionaryPage(){const search=state.search.trim().toLowerCase(),items=dictionary.filter(d=>[d.term,d.short].some(v=>v.toLowerCase().includes(search)));return shell(`${pageTop('Medical Dictionary','A plain-language guide to terms you might encounter in your care.')}<div class="dictionary-search">${icon('search')}<input class="search-input" id="dictionary-search" type="search" placeholder="Search a medical term..." value="${esc(state.search)}" aria-label="Search medical dictionary"></div>${state.term?`<div class="panel term-detail"><button class="btn btn-plain btn-sm" id="back-terms">← All terms</button><span class="eyebrow">Medical dictionary</span><h2>${esc(state.term.term)}</h2><p>${esc(state.term.short)}</p><h3>In a little more detail</h3><p>${esc(state.term.detail)}</p><h3>Why doctors check it</h3><p>${esc(state.term.why)}</p><h3>Good to know</h3><p>${esc(state.term.context)}</p></div>`:''}<div class="dictionary-grid">${items.map(d=>`<button class="term-card" data-term="${esc(d.term)}"><span class="feature-icon">${icon('book')}</span><strong>${esc(d.term)}</strong><span>${esc(d.short)}</span></button>`).join('')}</div>${!items.length?`<div class="empty-state">${icon('search')}<strong>No terms found</strong><p>Try a different spelling or a broader search.</p></div>`:''}`)}
function historyRow(d){return `<div class="history-row"><span class="feature-icon">${icon(toolInfo[d.kind].icon,'icon-sm')}</span><div><strong>${esc(d.name)}</strong><small>${esc(toolInfo[d.kind].title)} · ${esc(d.date)} · ${d.saved?'Saved to Supabase':'This session only'}</small></div><a class="btn btn-soft btn-sm" href="#/${d.kind}" data-open-doc="${d.id}">Open</a><button class="icon-button" data-delete-doc="${d.id}" aria-label="Delete ${esc(d.name)}">${icon('trash','icon-sm')}</button></div>`}
function historyPage(){return shell(`${pageTop('Document History',state.account?'Saved documents from your Supabase account and unsaved documents from this session.':'Sign in to save and access your documents across devices.',state.account?'<span class="status-badge">Private account</span>':'<a class="btn btn-primary btn-sm" href="#/login">Sign in</a>')}<div class="panel"><h3>Your documents</h3>${state.docs.length?state.docs.map(historyRow).join(''):`<div class="empty-state">${icon('clock')}<strong>Nothing here yet</strong><p>Upload a document, then choose Save to my account to keep its extracted text.</p><a href="#/reports" class="btn btn-primary btn-sm" style="margin-top:16px">Upload a report</a></div>`}</div><div style="margin-top:22px">${notice('Only documents you choose to save are stored in Supabase. Original uploaded files are not stored. Saved extracted text is private to your signed-in account under row-level security.')}</div>`)}
function profile(){return shell(`${pageTop('Your Profile',state.account?'Your Supabase account and saved documents.':'Sign in to manage your account.')}<div class="panel" style="max-width:650px"><h3>Account details</h3>${state.account?`<p style="font-size:13px">Signed in as <strong>${esc(state.account.email)}</strong></p><div class="field"><label for="profile-name">Display name</label><input id="profile-name" value="${esc(state.account.user_metadata?.full_name||'')}" placeholder="Your name"></div><button id="save-profile" class="btn btn-primary btn-sm">Update profile</button><button id="signout" class="btn btn-outline btn-sm" style="margin-left:8px">Sign out</button>`:`<p>You're not signed in.</p><a href="#/login" class="btn btn-primary btn-sm">Sign in</a>`}<div class="divider"></div>${notice('Your profile is managed by Supabase Auth. Original documents stay in your browser; only extracted text you explicitly save goes into your private Supabase table.')}</div>`)}
function auth(signup){return `<main class="auth-page"><div class="auth-art"><div class="auth-art-inner"><div class="auth-symbol">${icon('heart')}</div><span class="eyebrow">Health made simpler</span><h2>Understand more. Worry less.</h2><p>A thoughtful space to organize documents and prepare for better conversations about your health.</p></div></div><div class="auth-form-wrap"><div class="auth-box"><span class="eyebrow">Welcome to Medi Guide</span><h1>${signup?'Create your account':'Welcome back'}</h1><p>${signup?'Create a free Supabase account to save reviewed documents.':'Sign in to access your saved documents and AI tools.'}</p>${state.supabaseConfigured?`<button type="button" class="btn btn-outline google-auth" id="google-auth" ${state.authBusy||!state.supabase?'disabled':''}><svg class="google-mark" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.35 12.23c0-.71-.06-1.38-.18-2.04H12v3.87h5.24a4.48 4.48 0 0 1-1.94 2.94v2.44h3.14c1.84-1.69 2.91-4.18 2.91-7.21z"/><path fill="#34A853" d="M12 21.75c2.62 0 4.82-.87 6.43-2.35l-3.14-2.44c-.87.58-1.99.93-3.29.93-2.53 0-4.67-1.71-5.44-4.01H3.33v2.51A9.75 9.75 0 0 0 12 21.75z"/><path fill="#FBBC05" d="M6.56 13.88a5.86 5.86 0 0 1 0-3.76V7.61H3.33a9.75 9.75 0 0 0 0 8.78l3.23-2.51z"/><path fill="#EA4335" d="M12 6.11c1.42 0 2.68.49 3.68 1.44l2.76-2.76A9.26 9.26 0 0 0 12 2.25a9.75 9.75 0 0 0-8.67 5.36l3.23 2.51c.77-2.3 2.91-4.01 5.44-4.01z"/></svg>${state.authBusy?'Connecting...':'Continue with Google'}</button><div class="auth-divider"><span>or continue with email</span></div><form id="auth-form">${signup?`<div class="field"><label for="auth-name">Your name</label><input id="auth-name" type="text" required placeholder="Your name" maxlength="80"></div>`:''}<div class="field"><label for="auth-email">Email</label><input id="auth-email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" type="password" required minlength="6" autocomplete="${signup?'new-password':'current-password'}" placeholder="At least 6 characters"></div><button class="btn btn-primary" ${state.authBusy?'disabled':''}>${state.authBusy?'Please wait...':signup?'Create account':'Sign in'} ${icon('arrow','icon-sm')}</button></form><p class="auth-switch">${signup?'Already have an account?':'New to Medi Guide?'} <a href="#/${signup?'login':'signup'}">${signup?'Sign in':'Create an account'}</a></p>${notice('For sensitive medical data, review Supabase security settings, your AI provider’s data policy, and applicable privacy laws before production use.','warning')}`:notice('Supabase is not configured. Add SUPABASE_URL and SUPABASE_ANON_KEY to your local .env or Vercel environment settings.','warning')}</div></div></main>`}
async function signInWithGoogle(){
  if(!state.supabase){toast('Supabase is not ready yet.');return}
  state.authBusy=true;render();
  try{
    const callback=new URL(location.pathname,location.origin);
    callback.searchParams.set('auth_callback','google');
    const {error}=await state.supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:callback.toString()}});
    if(error)throw error;
  }catch(e){toast(e.message||'Could not start Google sign-in. Check that Google is enabled in Supabase.')}
  finally{state.authBusy=false;render()}
}
async function submitAuth(signup){if(!state.supabase){toast('Supabase is not ready yet.');return}const email=$('#auth-email').value.trim(),password=$('#auth-password').value;state.authBusy=true;render();try{let response;if(signup){const name=state.pendingName||'';response=await state.supabase.auth.signUp({email,password,options:{data:{full_name:name},emailRedirectTo:location.origin+'/#/dashboard'}})}else response=await state.supabase.auth.signInWithPassword({email,password});if(response.error)throw response.error;if(response.data.session){setAccount(response.data.user);go('dashboard')}else toast('Check your email for a confirmation link, then sign in.')}catch(e){toast(e.message||'Authentication failed.')}finally{state.authBusy=false;render()}}
function infoPage(kind){const blocks={
privacy:{title:'Privacy & Security',lead:'You should know exactly what happens to your health information.',sections:[['Your documents','Files are processed in your browser for text extraction. Original files are not uploaded to our server. Extracted text remains in this tab unless you explicitly choose to save it to your Supabase account. Saved text is protected by row-level security but is not a substitute for a clinically compliant health-record system.'],['When AI is used','When you explicitly analyze or send a question, extracted text and questions go to your selected configured AI provider through a server-side proxy. Free tiers may retain or use inputs differently, including for product improvement. Check each provider’s privacy terms before sending medical data.'],['Account limitations','Sign in and sign up use Supabase Auth. Saved document text lives in a Supabase table with per-user row-level security. A Supabase anon key is public by design; provider API keys remain on the server. This application has not been certified for regulated health data.'],['Third-party resources','Fonts, OCR, PDF parsing, and PDF export scripts are loaded from external CDNs. These providers may receive standard browser requests. Document content is processed locally by these scripts, not sent to them by our application.'],['Your choices','You can remove a document or clear session history at any time. Do not save or send information you are uncomfortable storing in your Supabase project or sharing with your selected AI provider.']]},
about:{title:'About Medi Guide',lead:'Your health documents, made simple.',sections:[['Why we built this','Medical documents can be confusing. Medi Guide helps you organize readable details, understand common terms, and prepare useful questions for your healthcare team.'],['How we approach health information','We focus on clear, cautious explanations. We do not invent missing information, diagnose conditions, change prescriptions, or interpret radiology images as definitive findings. You remain responsible for checking every extracted detail.'],['Built for your next conversation','The goal is not to replace a clinician. It is to help you arrive at the next appointment with more context and better questions.']]},
terms:{title:'Terms & Medical Disclaimer',lead:'Please read this before using Medi Guide.',sections:[['Educational use only','Medi Guide provides general educational information and document organization. It is not a licensed healthcare professional, a diagnostic device, or a substitute for medical advice, diagnosis, or treatment.'],['Verify everything','OCR and AI may misread or omit details. Review all extracted information against the original document and consult a qualified professional about medical decisions. Do not change medication or dosage based on this app.'],['Emergencies','Do not use Medi Guide for emergencies. Call your local emergency number or seek immediate emergency care if you believe you have an urgent medical concern.'],['Prototype limitations','This app uses Supabase Auth and optional private document storage, but has no clinical validation, compliance certification, or guaranteed service availability. Free API tiers have quotas and changing terms.']]}
};const b=blocks[kind];return shell(`<article class="info-page"><span class="eyebrow">Medi Guide</span><h1>${b.title}</h1><p class="lead">${b.lead}</p><div class="panel">${b.sections.map(([h,t])=>`<h2>${h}</h2><p>${t}</p>`).join('')}</div><div style="margin-top:24px">${notice('If you have urgent symptoms or suspect an emergency, contact local emergency services.','warning')}</div></article>`)}
function render(){state.route=route();state.menu=false;let content;switch(state.route){case '':case 'home':content=home();break;case 'dashboard':content=dashboard();break;case 'forms':case 'prescriptions':case 'reports':content=toolPage(state.route);break;case 'assistant':content=assistant();break;case 'dictionary':content=dictionaryPage();break;case 'history':content=historyPage();break;case 'profile':content=profile();break;case 'login':content=auth(false);break;case 'signup':content=auth(true);break;case 'privacy':case 'about':case 'terms':content=infoPage(state.route);break;default:content=home()}$('#app').innerHTML=header()+content;if(state.route==='assistant'){const area=$('#chat-messages');if(area)area.scrollTop=area.scrollHeight}}
window.addEventListener('hashchange',()=>{state.followup='';render();if(!location.hash.startsWith('#features'))window.scrollTo(0,0)});
async function status(){
  try{
    const [statusResponse,configResponse]=await Promise.all([fetch('/api/status'),fetch('/api/config')]);
    if(!statusResponse.ok||!configResponse.ok)throw Error('Configuration endpoints unavailable.');
    const info=await statusResponse.json(),config=await configResponse.json();
    state.providers=info.providers||[];
    state.ai=state.providers.length>0;
    if(!state.providers.includes(state.provider))state.provider=state.providers[0]||'';
    state.supabaseConfigured=Boolean(config.supabaseUrl&&config.supabaseAnonKey);
    render();
    if(state.supabaseConfigured){
      await loadLibrary('Supabase','https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js');
      state.supabase=window.supabase.createClient(config.supabaseUrl,config.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
      const {data:{session}}=await state.supabase.auth.getSession();
      setAccount(session?.user||null);
      if(new URLSearchParams(location.search).get('auth_callback')==='google'){
        const failed=new URLSearchParams(location.search).has('error')||new URLSearchParams(location.hash.slice(1)).has('error');
        history.replaceState(null,'',location.pathname+'#/login');
        if(session?.user&&!failed)go('dashboard');
        else toast('Google sign-in was cancelled or unavailable. Try again or use email.');
      }
      state.supabase.auth.onAuthStateChange((_event,newSession)=>setAccount(newSession?.user||null));
    }
  }catch(e){toast('Could not initialize server configuration: '+e.message);render()}
}
async function api(path,data){
  if(!state.supabase||!state.account)throw Error('Sign in with Supabase to use AI features.');
  const {data:{session}}=await state.supabase.auth.getSession();
  if(!session?.access_token)throw Error('Your session expired. Please sign in again.');
  const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},body:JSON.stringify({...data,provider:state.provider})});
  let json;try{json=await res.json()}catch{throw Error('Could not reach the AI service.')}
  if(!res.ok)throw Error(json.error||'AI request failed.');return json
}
function validate(file){if(!file)return 'Choose a file to continue.';if(!(['application/pdf','image/jpeg','image/png'].includes(file.type)||/\.(pdf|jpe?g|png)$/i.test(file.name)))return 'Only PDF, JPG, JPEG, and PNG files are supported.';if(file.size>15*1024*1024)return 'This file is over the 15 MB limit.';if(!file.size)return 'This file appears to be empty.';return ''}
const libraries={};
function loadLibrary(name,url){if(!libraries[name])libraries[name]=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=url;script.onload=resolve;script.onerror=()=>reject(Error('Could not load '+name+'. Check your internet connection.'));document.head.append(script)}).catch(e=>{delete libraries[name];throw e});return libraries[name]}
const loadOCR=()=>loadLibrary('OCR','https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js');
const loadPDF=()=>loadLibrary('PDF reader','https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');
function pdfPageText(items){let text='',previousY=null,previousEndedLine=false;for(const item of items){if(!item.str){if(item.hasEOL)previousEndedLine=true;continue}const y=item.transform?.[5];if(text)text+=previousEndedLine||previousY!==null&&Number.isFinite(y)&&Math.abs(y-previousY)>2?'\n':' ';text+=item.str;previousEndedLine=Boolean(item.hasEOL);if(Number.isFinite(y))previousY=y}return text}
async function readFile(file){const pdf=file.type==='application/pdf'||/\.pdf$/i.test(file.name);if(pdf){await loadPDF();window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdfDoc=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;const chunks=[];for(let i=1;i<=Math.min(pdfDoc.numPages,5);i++){const page=await pdfDoc.getPage(i);const extracted=pdfPageText((await page.getTextContent()).items);if(extracted.trim().length>30){chunks.push(`Page ${i}\n${extracted}`)}else{await loadOCR();const viewport=page.getViewport({scale:1.6});const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const ocr=await window.Tesseract.recognize(canvas,'eng');chunks.push(`Page ${i}\n${ocr.data.text}`)}}return chunks.join('\n\n').slice(0,40000)}await loadOCR();const result=await window.Tesseract.recognize(file,'eng');return (result.data.text||'').slice(0,40000)}
function localResult(kind,text){if(kind==='forms'){
  const fields=[];
  text.split('\n').forEach(line=>{
    const cleaned=line.trim();
    if(!cleaned||cleaned.length>100)return;
    const match=cleaned.match(/^([A-Za-z][A-Za-z\s()/.-]{2,45}\*?)\s*:\s*(.{0,55})$/)||cleaned.match(/^([A-Za-z][A-Za-z\s()/.-]{2,45}\*?)\s+([_.-]{3,})$/);
    if(match){
      const value=match[2].trim();
      fields.push({label:match[1].replace(/\*$/,'').trim(),value:/^[_.-]{3,}$/.test(value)?'':value,required:/\*$|\(required\)/i.test(match[1]),unclear:false});
    }else{
      const box=cleaned.match(/^(?:\[([ xX])\]|([☐☑□■]))\s*(.{3,60})$/);
      if(box)fields.push({label:box[3].trim(),value:/[xX☑■]/.test(box[1]||box[2])?'Checked':'Not checked',required:false,unclear:false});
    }
  });
  return {summary:fields.length?`${fields.length} clearly labeled field${fields.length===1?' was':'s were'} found in the extracted text. Please check each against the original form.`:'No clearly labeled fields were found. Add fields manually after checking the original form.',fields:fields.slice(0,40),warnings:['OCR can miss checkboxes, handwriting, and form layout. Review the original document carefully.'],questions:[]};
}
if(kind==='prescriptions')return {summary:'Text was extracted for your review. Without AI, medication details are left blank rather than inferred from OCR. Add only information you can verify.',medicines:[],date:'',doctorNotes:'',abbreviations:[],warnings:['Check medicine names, doses, frequency, and duration with the original prescription or your pharmacist.'],questions:['Which instructions should I confirm with my prescriber or pharmacist?']};const rows=[];text.split('\n').forEach(line=>{const match=line.trim().match(/^([A-Za-z][A-Za-z\s()/-]{2,35})\s*[:\s]\s*(\d+(?:[.,]\d+)?)\s*([%µμa-zA-Z/0-9^.-]{0,12})\s*(?:\(?\s*(?:ref(?:erence)?(?:\s*range)?\s*[:=]?\s*)?(\d+(?:[.,]\d+)?\s*[-–]\s*\d+(?:[.,]\d+)?\s*[%µμa-zA-Z/0-9^.-]{0,12})\s*\)?)?\s*(?:\b(High|Low|H|L)\b)?\s*$/i);if(match&&rows.length<30){rows.push({name:match[1].trim(),value:match[2],unit:match[3]||'',range:match[4]||'',flag:match[5]?({H:'High',L:'Low'}[match[5].toUpperCase()]||match[5]):'',explanation:''})}});return {summary:rows.length?`${rows.length} labeled value${rows.length===1?' was':'s were'} found in the OCR text. This is not a medical interpretation; verify values and ranges against your original report.`:'No clearly formatted lab values were found. Review the extracted text below or enable AI to summarize written findings.',parameters:rows,warnings:['OCR may omit or misread values, units, and ranges. Verify every result against your report.'],questions:['Which findings should I discuss with my healthcare professional?']}}
async function processFile(file,kind,forChat=false){const error=validate(file);if(error){toast(error);return}if(!forChat){state.processing=true;state.activeDoc=null;render()}else toast('Reading document. This may take a moment...');try{const text=await readFile(file);if(!text.trim())throw Error('No readable text was found. Try a clearer image or a searchable PDF.');const doc={id:Date.now()+Math.random(),kind,name:file.name,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}),text,result:localResult(kind,text),aiAnalyzed:false,error:''};state.docs.unshift(doc);state.docs=state.docs.slice(0,20);if(forChat){state.chatContext=doc;toast('Document attached. Ask a question about its extracted text.')}else{state.activeDoc=doc;state.followup='';}}catch(e){if(!forChat){state.activeDoc=null;toast(e.message)}else toast(e.message)}finally{state.processing=false;render()}}
async function analyze(doc){if(!state.ai||!doc.text)return;state.processing=true;render();try{const response=await api('analyze',{kind:toolInfo[doc.kind].label,text:doc.text});if(response.result&&typeof response.result==='object'){doc.result=response.result;doc.aiAnalyzed=true;doc.error=''}else throw Error('Analysis returned an unexpected result.')}catch(e){doc.error=e.message+' Showing conservative OCR results instead.'}finally{state.processing=false;render()}}
const emergencyPattern=/\b(chest pain|can't breathe|cannot breathe|difficulty breathing|trouble breathing|stroke|unconscious|severe bleeding|overdose|suicidal|anaphylaxis|severe allergic reaction|seizure)\b/i;
const emergencyMessage='If this is happening now or you think someone may be in immediate danger, call your local emergency number or go to the nearest emergency department now. Do not wait for a response here. I cannot assess an emergency or provide a diagnosis.';
async function sendChat(question){if(!question.trim()||state.chatBusy)return;const previous=state.chat.filter(m=>m.role==='user'||m.role==='assistant').slice(-8);state.chat.push({role:'user',content:question.trim()});if(emergencyPattern.test(question)){state.chat.push({role:'assistant',content:emergencyMessage});render();return}state.chatBusy=true;render();try{if(!state.ai)throw Error('AI is not configured. You can explore the Medical Dictionary, or ask the server administrator to configure a free-tier provider key.');const result=await api('chat',{question:question.trim(),context:state.chatContext?.text||'',history:previous});state.chat.push({role:'assistant',content:result.answer})}catch(e){state.chat.push({role:'assistant',content:e.message})}finally{state.chatBusy=false;render()}}
async function followup(question){const doc=state.activeDoc;if(!doc||!question.trim())return;if(emergencyPattern.test(question)){state.followup=emergencyMessage;render();return}state.followupBusy=true;render();try{if(!state.ai)throw Error('AI follow-ups are unavailable until a free-tier provider is configured and you sign in. You can review the extracted text and use the Medical Dictionary.');const result=await api('chat',{question,context:doc.text,history:[]});state.followup=result.answer}catch(e){state.followup=e.message}finally{state.followupBusy=false;render()}}
async function download(doc){try{await loadLibrary('PDF export','https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.2/jspdf.umd.min.js')}catch(e){toast(e.message);return}const pdf=new window.jspdf.jsPDF(),margin=18,width=174;let y=20;const line=(text,size=10,bold=false)=>{pdf.setFont('helvetica',bold?'bold':'normal');pdf.setFontSize(size);const lines=pdf.splitTextToSize(String(text),width);if(y+lines.length*(size*.48)+8>275){pdf.addPage();y=20}pdf.text(lines,margin,y);y+=lines.length*(size*.48)+8};line('Medi Guide - Reviewed form fields',16,true);line('Source: '+doc.name+'  |  Exported: '+new Date().toLocaleDateString(),9);line('This is a reviewed field summary, NOT the original completed form. Verify every entry.',9);y+=5;(doc.result.fields||[]).forEach((f,i)=>{line(`${i+1}. ${f.label||'Untitled field'}${f.required?' (required)':''}`,10,true);line(f.value||'[Not provided]',10)});line('For educational use. Do not use as a substitute for an official form or medical advice.',8);pdf.save('medi-guide-reviewed-fields.pdf')}
let cameraStream=null;
async function openCamera(){if(!navigator.mediaDevices?.getUserMedia){$('#camera-input')?.click();return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const overlay=document.createElement('div');overlay.className='camera-overlay';overlay.id='camera-overlay';overlay.innerHTML=`<div class="camera-dialog" role="dialog" aria-modal="true" aria-label="Scan document with camera"><header><h2>Scan with your camera</h2><button class="icon-button" id="close-camera" aria-label="Close camera">${icon('close')}</button></header><video id="camera-video" autoplay playsinline muted></video><footer><button class="btn btn-outline btn-sm" id="cancel-camera">Cancel</button><button class="btn btn-primary btn-sm" id="capture-camera">${icon('camera','icon-sm')} Capture document</button></footer></div>`;document.body.append(overlay);$('#camera-video').srcObject=cameraStream}catch{toast('Camera unavailable or permission denied. You can upload a photo instead.');$('#camera-input')?.click()}}
function closeCamera(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;$('#camera-overlay')?.remove()}
document.addEventListener('click',async e=>{
  const target=e.target.closest('button,a');if(!target)return;
  if(target.id==='menu-toggle'){state.menu=!state.menu;$('#menu-toggle').setAttribute('aria-expanded',state.menu);$('.mobile-nav')?.classList.toggle('open',state.menu)}
  if(target.id==='theme-toggle')toggleTheme();
  if(target.id==='google-auth')signInWithGoogle();
  if(target.id==='browse-btn'){e.stopPropagation();$('#document-input')?.click()}
  if(target.id==='camera-btn'){e.stopPropagation();openCamera()}
  if(target.id==='clear-doc'){state.activeDoc=null;state.followup='';render()}
  if(target.id==='retry-ai'&&state.activeDoc)analyze(state.activeDoc);
  if(target.id==='save-doc'&&state.activeDoc)saveDocument(state.activeDoc);
  if(target.id==='download-pdf'&&state.activeDoc)download(state.activeDoc);
  if(target.id==='ask-about-doc'&&state.activeDoc)state.chatContext=state.activeDoc;
  if(target.dataset.add&&state.activeDoc){const key=target.dataset.add;if(!Array.isArray(state.activeDoc.result[key]))state.activeDoc.result[key]=[];state.activeDoc.result[key].push(key==='fields'?{label:'',value:'',required:false,unclear:false}:key==='parameters'?{name:'',value:'',unit:'',range:'',flag:'',explanation:''}:{name:'',dosage:'',frequency:'',duration:'',instructions:'',purpose:'',unclear:false});render()}
  if(target.dataset.remove&&state.activeDoc){state.activeDoc.result[target.dataset.remove]?.splice(Number(target.dataset.index),1);render()}
  if(target.dataset.suggest)sendChat(target.dataset.suggest);
  if(target.dataset.term){state.term=dictionary.find(d=>d.term===target.dataset.term);render();window.scrollTo(0,0)}
  if(target.id==='back-terms'){state.term=null;render()}
  if(target.dataset.openDoc)state.activeDoc=state.docs.find(d=>String(d.id)===target.dataset.openDoc);
  if(target.dataset.deleteDoc){const doc=state.docs.find(d=>String(d.id)===target.dataset.deleteDoc);if(doc&&confirm('Delete this document'+(doc.saved?' from Supabase':' from this session')+'?'))deleteDocument(doc)}
  if(target.id==='chat-upload'||target.id==='chat-upload-inline')$('#chat-file')?.click();
  if(target.id==='save-profile'&&state.supabase){const {error}=await state.supabase.auth.updateUser({data:{full_name:$('#profile-name').value.trim().slice(0,80)}});if(error)toast(error.message);else{toast('Profile updated.');render()}}
  if(target.id==='signout'&&state.supabase){const {error}=await state.supabase.auth.signOut();if(error)toast(error.message);else{setAccount(null);go('home');toast('Signed out.')}}
  if(target.id==='close-camera'||target.id==='cancel-camera')closeCamera();
  if(target.id==='capture-camera'){const video=$('#camera-video'),canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{closeCamera();if(blob)processFile(new File([blob],`camera-scan-${Date.now()}.jpg`,{type:'image/jpeg'}),state.route)},'image/jpeg',.9)}
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='document-input'||t.id==='camera-input'){processFile(t.files?.[0],state.route);t.value=''}if(t.id==='chat-file'){processFile(t.files?.[0],'reports',true);t.value=''}if(t.id==='context-doc'){state.chatContext=state.docs.find(d=>String(d.id)===t.value)||null;render()}if(t.id==='ai-provider'){state.provider=t.value;localStorage.setItem('medi-guide-provider',t.value);render()}if(t.dataset.edit&&t.type==='checkbox'&&state.activeDoc){const row=state.activeDoc.result[t.dataset.edit]?.[Number(t.dataset.index)];if(row){row[t.dataset.field]=t.checked;render()}}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.edit&&state.activeDoc){const row=state.activeDoc.result[t.dataset.edit]?.[Number(t.dataset.index)];if(row)row[t.dataset.field]=t.value}if(t.dataset.resultField&&state.activeDoc)state.activeDoc.result[t.dataset.resultField]=t.value;if(t.id==='dictionary-search'){const pos=t.selectionStart;state.search=t.value;render();const input=$('#dictionary-search');input?.focus();input?.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{e.preventDefault();const id=e.target.id;if(id==='auth-form'){state.pendingName=$('#auth-name')?.value.trim().slice(0,80)||'';submitAuth(state.route==='signup')}if(id==='chat-form')sendChat($('#chat-input').value);if(id==='followup-form')followup($('#followup-question').value)});
document.addEventListener('click',e=>{if(e.target.closest('#upload-zone')&&!e.target.closest('button'))$('#document-input')?.click()});
document.addEventListener('dragover',e=>{if(e.target.closest('#upload-zone')){e.preventDefault();$('#upload-zone')?.classList.add('dragging')}});
